SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Blog redesign (2026-11-07): the /blog/ page hero (H1 + lead) — editable in CMS → Pages → /blog/ → block hero.
-- H1 keeps the old keyword "บทความ" → "บทความ / ความรู้". Page title, SEO title, description and URL are unchanged.
-- Only applied while the page has no blocks (never overwrites CMS edits).
-- lead: อัปเดตเทรนด์ MLM กลยุทธ์ธุรกิจ เทคนิคการบริหารเครือข่าย และความรู้ด้านเทคโนโลยีที่ช่วยให้ธุรกิจขายตรงเติบโตอย่างยั่งยืน

UPDATE pages SET blocks = CONVERT(X'' USING utf8mb4), updated_at = NOW()
WHERE path = CONVERT(X'2F626C6F672F' USING utf8mb4) COLLATE utf8mb4_bin AND locale = 'th' AND deleted_at IS NULL
  AND (blocks IS NULL OR JSON_LENGTH(blocks) = 0);
